import {controller, target} from '@github/catalyst'

@controller
class SynchronousPaymentElement extends HTMLElement {
  @target declare buttonCTA: HTMLElement
  @target declare loadingStatus: HTMLElement
  @target declare buttonElement: HTMLButtonElement

  connectedCallback() {
    this.loadingStatus.style.display = 'none'
  }

  collectPayment() {
    this.buttonElement.disabled = true
    this.buttonCTA.textContent = 'Upgrading'
    this.loadingStatus.style.display = ''
  }
}
