import {controller, target, attr} from '@github/catalyst'

@controller
export default class InvoiceDownloadElement extends HTMLElement {
  @attr declare url: string
  @attr declare transaction: string
  @target declare loadingSpinner: HTMLElement
  @target declare elementToHide: HTMLElement
  @target declare anchorContainer: HTMLElement
  @target declare downloadAnchor: HTMLAnchorElement

  connectedCallback() {
    this.loadingSpinner.style.display = 'none'
  }

  disconnectedCallback() {
    this.loadingSpinner.style.display = 'none'
    this.elementToHide.style.display = ''
  }

  disableDownload() {
    this.downloadAnchor.classList.add('Link--muted')
    this.downloadAnchor.style.pointerEvents = 'none'
    this.anchorContainer.style.cursor = 'not-allowed'
  }

  enableDownload() {
    this.downloadAnchor.classList.remove('Link--muted')
    this.downloadAnchor.style.pointerEvents = ''
    this.anchorContainer.style.cursor = ''
  }

  startDownload(event: Event) {
    event.preventDefault()
    this.loadingSpinner.style.display = ''
    this.elementToHide.style.display = 'none'
    this.downloadFile(this.url)
  }

  async downloadFile(url: string) {
    try {
      this.disableDownload()
      const response = await fetch(url)
      if (response.ok) {
        const blob = await response.blob()
        const fileName = this.getFileName(response, blob)
        this.sendFileToBrowser(blob, fileName)
      } else {
        if (response.status === 404) {
          this.dispatchEvent(
            new CustomEvent('no-invoice-found', {bubbles: true, detail: {transactionId: this.transaction}}),
          )
        } else if (response.status === 504) {
          // This is a timeout error
          this.dispatchEvent(
            new CustomEvent('invoice-download-timeout', {bubbles: true, detail: {transactionId: this.transaction}}),
          )
        } else {
          this.dispatchEvent(new CustomEvent('invoice-download-error', {bubbles: true, detail: {}}))
        }
      }
    } catch {
      this.dispatchEvent(new CustomEvent('invoice-download-error', {bubbles: true, detail: {}}))
    } finally {
      this.dispatchEvent(new CustomEvent('invoice-download-complete', {bubbles: true, detail: {}}))
      this.loadingSpinner.style.display = 'none'
      this.elementToHide.style.display = ''
      this.enableDownload()
    }
  }

  sendFileToBrowser(blob: Blob, fileName: string) {
    // This creates the url that the file will be downloaded from
    const downloadUrl = URL.createObjectURL(blob)

    // This adds a temporary anchor element to the DOM to trigger the download
    // It is subsequently removed since it isn't necessary after the download
    const a = document.createElement('a')
    a.href = downloadUrl
    a.download = fileName
    document.body.appendChild(a)
    a.click()
    a.remove()

    // This revokes the object URL since the URL is no longer needed
    URL.revokeObjectURL(downloadUrl)
  }

  getFileName(response: Response, blob: Blob): string {
    const contentDisposition = response.headers.get('Content-Disposition')
    if (contentDisposition) {
      const fileName = contentDisposition.match(/filename="(.+)"/)?.[1]
      if (fileName) {
        return fileName
      }
    }
    const fileType = blob.type
    if (fileType === 'application/pdf') {
      return 'invoice.pdf'
    } else if (fileType === 'application/zip') {
      return 'invoices.zip'
    } else {
      return 'invoice'
    }
  }
}
